"""Bouwt en/index.html en de/index.html uit de Nederlandse index.html.
Elke NL-tekst moet exact gevonden worden; anders stopt het script."""
import pathlib, re, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
src = (ROOT / "index.html").read_text(encoding="utf-8")
# finalize.py bakt een datum in de bron; zet de tokens terug zodat de bron token-vrij blijft
_norm = re.sub(r'(<p class="updated">[^<]*)<time datetime="[\d-]+">[^<]*</time>', r'\1<time datetime="@@LASTMOD@@">@@LASTMOD_H@@</time>', src)
if _norm != src:
    (ROOT / "index.html").write_text(_norm, encoding="utf-8")
    src = _norm
# SEO/GEO-blok wordt per taal opnieuw gemaakt door tools/seo.py
src = re.sub(r"<!-- SEO:START.*?<!-- SEO:END -->\n?", "", src, flags=re.S)
src = re.sub(r' srcset="[^"]*" sizes="[^"]*"', "", src)
src = re.sub(r'<script type="application/ld\+json">.*?</script>\n?', "", src, flags=re.S)

# Structurele vervangingen (paden, ankers, taalknoppen) per taal
def structural(lang):
    ids = {
        "en": {"over": "about", "seizoenen": "seasons", "wildschonau": "wildschoenau",
               "bereikbaarheid": "getting-there", "praktisch": "practical", "verblijf": "stay", "geschiedenis": "history", "lanerkoepfl": "lanerkoepfl", "activiteiten": "activities", "natuur": "nature", "dier": "pets", "fotos": "gallery"},
        "de": {"over": "dorf", "seizoenen": "jahreszeiten", "wildschonau": "wildschoenau",
               "bereikbaarheid": "anreise", "praktisch": "praktisch", "verblijf": "unterkunft", "geschiedenis": "geschichte", "lanerkoepfl": "lanerkoepfl", "activiteiten": "aktivitaeten", "natuur": "natur", "dier": "tiere", "fotos": "galerie"},
    }[lang]
    pairs = []
    for nl, new in ids.items():
        pairs += [(f'id="{nl}"', f'id="{new}"'), (f'href="#{nl}"', f'href="#{new}"')]
    pairs += [
        ('href="assets/', 'href="../assets/'),
        ('src="assets/', 'src="../assets/'),
        ('<html lang="nl">', f'<html lang="{lang}">'),
        ('<link rel="canonical" href="https://niederau.nl/">', f'<link rel="canonical" href="https://niederau.nl/{lang}/">'),
        ('<meta property="og:url" content="https://niederau.nl/">', f'<meta property="og:url" content="https://niederau.nl/{lang}/">'),
        ('"url": "https://niederau.nl/",', f'"url": "https://niederau.nl/{lang}/",'),
        ('"inLanguage": "nl",', f'"inLanguage": "{lang}",'),
        ('<meta property="og:locale" content="nl_NL">', '<meta property="og:locale" content="%s">' % ("en_GB" if lang == "en" else "de_DE")),
        ('<a href="./" hreflang="nl" lang="nl" aria-current="true">NL</a>', '<a href="../" hreflang="nl" lang="nl">NL</a>'),
        ('<a href="en/" hreflang="en" lang="en">EN</a>',
         '<a href="./" hreflang="en" lang="en" aria-current="true">EN</a>' if lang == "en" else '<a href="../en/" hreflang="en" lang="en">EN</a>'),
        ('<a href="de/" hreflang="de" lang="de">DE</a>',
         '<a href="./" hreflang="de" lang="de" aria-current="true">DE</a>' if lang == "de" else '<a href="../de/" hreflang="de" lang="de">DE</a>'),
    ]
    return pairs

